#!/usr/bin/env python3
"""Unit tests for the offline Wayland VRR trace analyzer; no display required."""

import importlib.util
import pathlib
import sys
import unittest

# Do not leave generated bytecode in the source tree when loading the tool.
sys.dont_write_bytecode = True
path = pathlib.Path(__file__).resolve().parents[1] / 'TOOLS' / 'wayland-vrr-trace.py'
spec = importlib.util.spec_from_file_location('wayland_vrr_trace', path)
trace = importlib.util.module_from_spec(spec)
spec.loader.exec_module(trace)


class TraceTests(unittest.TestCase):
    def test_modern_buffer_and_callback_only_commits(self):
        lines = '''
[12:00:00.000000] {Default Queue} -> wl_surface#7.frame(new id wl_callback#8)
[12:00:00.000001] {Default Queue} -> wp_presentation#2.feedback(wl_surface#7, new id wp_presentation_feedback#9)
[12:00:00.001000] {Default Queue} -> wl_surface#7.attach(wl_buffer#10, 0, 0)
[12:00:00.001010] {Default Queue} -> wl_surface#7.damage_buffer(0, 0, 1920, 1080)
[12:00:00.002000] {Default Queue} -> wl_surface#7.commit()
[12:00:00.010000] {Default Queue} wl_callback#8.done(5000)
[12:00:00.011000] {Default Queue} wp_presentation_feedback#9.presented(0, 5, 0, 16666666, 0, 0, 7)
[12:00:00.012000] {Default Queue} -> wp_presentation_feedback#9.destroy()
[12:00:00.020000] {Default Queue} -> wl_surface#7.frame(new id wl_callback#8)
[12:00:00.022000] {Default Queue} -> wl_surface#7.commit()
[12:00:00.030000] {Default Queue} wl_callback#8.done(5020)
[12:00:00.041000] {Default Queue} -> wl_surface#7.attach(wl_buffer#11, 0, 0)
[12:00:00.042000] {Default Queue} -> wl_surface#7.commit()
'''.splitlines()
        result = trace.analyze(lines)
        self.assertEqual(result['protocol_lines'], 13)
        state = result['surfaces']['7']
        self.assertEqual(state['commits']['count'], 3)
        self.assertAlmostEqual(state['buffer_or_damage']['median_ms'], 40)
        self.assertEqual(state['callback_only_commits']['count'], 1)
        self.assertEqual(state['callback_requests'], 2)
        self.assertEqual(state['callback_done']['count'], 2)
        self.assertEqual(state['feedback_latched'], 1)
        self.assertEqual(state['feedback_presented'], 1)
        self.assertEqual(state['feedback_cancelled'], 0)
        self.assertFalse(state['feedback_records'][0]['zero_copy'])
        self.assertEqual(state['feedback_records'][0]['timestamp_ns'], 5000000000)

    def test_old_style_and_metadata(self):
        lines = '''
[1000.000] -> xdg_wm_base@3.get_xdg_surface(new id xdg_surface@4, wl_surface@7)
[1000.100] -> xdg_toplevel@5.set_app_id("love")
[1000.200] -> xdg_toplevel@5.set_fullscreen(nil)
[1000.300] -> wl_surface@7.set_opaque_region(wl_region@6)
[1000.400] -> wl_surface@7.set_buffer_scale(1)
[1000.500] -> wl_surface@7.commit()
[1040.500] -> wl_surface@7.damage(0, 0, 1280, 720)
[1040.600] -> wl_surface@7.commit()
'''.splitlines()
        result = trace.analyze(lines)
        self.assertEqual(len(result['metadata']), 3)
        state = result['surfaces']['7']
        self.assertEqual(state['other_commits']['count'], 1)
        self.assertEqual(state['buffer_or_damage']['count'], 1)
        self.assertEqual(state['opaque_regions'], ['wl_region@6'])
        self.assertEqual(state['buffer_scales'], ['1'])

    def test_discard_cancel_and_unknown_events(self):
        lines = '''
[1000.0] -> wp_presentation@2.feedback(wl_surface@7, new id wp_presentation_feedback@9)
[1001.0] -> wl_surface@7.commit()
[1010.0] wp_presentation_feedback@9.discarded()
[1011.0] -> wp_presentation_feedback@9.destroy()
[1020.0] -> wp_presentation@2.feedback(wl_surface@7, new id wp_presentation_feedback@9)
[1021.0] -> wp_presentation_feedback@9.destroy()
[1022.0] wl_callback@20.done(5000)
[1023.0] wp_presentation_feedback@30.discarded()
'''.splitlines()
        state = trace.analyze(lines)['surfaces']['7']
        self.assertEqual(state['feedback_discarded'], 1)
        self.assertEqual(state['feedback_cancelled'], 1)
        self.assertEqual(state['feedback_unreplied'], 0)
        self.assertEqual(state['callback_done']['count'], 0)

    def test_window_keeps_prior_requests_and_separate_feedback_clock(self):
        lines = '''
[1000.0] -> wl_surface@7.frame(new id wl_callback@8)
[1000.0] -> wp_presentation@2.feedback(wl_surface@7, new id wp_presentation_feedback@9)
[1000.0] -> wl_surface@7.damage(0, 0, 100, 100)
[1000.0] -> wl_surface@7.commit()
[1040.0] wl_callback@8.done(4000)
[1040.0] wp_presentation_feedback@9.presented(0, 40, 0, 16666666, 0, 0, 7)
[1040.0] -> wl_surface@7.damage(0, 0, 100, 100)
[1040.0] -> wl_surface@7.commit()
[1041.0] -> wp_presentation@2.feedback(wl_surface@7, new id wp_presentation_feedback@10)
[1080.0] -> wl_surface@7.damage(0, 0, 100, 100)
[1080.0] -> wl_surface@7.commit()
[1080.0] wp_presentation_feedback@10.presented(0, 40, 40000000, 16666666, 0, 0, 7)
[1120.0] -> wl_surface@7.damage(0, 0, 100, 100)
[1120.0] -> wl_surface@7.commit()
'''.splitlines()
        result = trace.analyze(lines, start_seconds=.04, duration_seconds=.041)
        state = result['surfaces']['7']
        self.assertEqual(state['commits']['count'], 2)
        self.assertAlmostEqual(state['buffer_or_damage']['median_ms'], 40)
        self.assertEqual(state['callback_done']['count'], 1)
        self.assertEqual(state['callback_requests'], 1)
        self.assertEqual(state['feedback_requests'], 2)
        self.assertEqual(state['feedback_latched'], 2)
        self.assertAlmostEqual(state['presentation_timestamps']['median_ms'], 40)
        self.assertEqual(state['feedback_records'][0]['relative_receipt_ms'], 40)
        self.assertEqual(result['cadence_window']['counters_scope'], 'whole capture')
        empty = trace.analyze(lines, start_seconds=5)['surfaces']['7']
        self.assertEqual(empty['commits']['count'], 0)
        self.assertEqual(empty['feedback_presented'], 2)

    def test_invalid_window(self):
        for start in (-1, float('nan'), float('inf')):
            with self.assertRaises(ValueError):
                trace.analyze([], start_seconds=start)
        for duration in (0, -1, float('nan'), float('inf')):
            with self.assertRaises(ValueError):
                trace.analyze([], duration_seconds=duration)

    def test_midnight_and_empty_log(self):
        lines = '''
[23:59:59.980000] -> wl_surface#7.damage(0, 0, 100, 100)
[23:59:59.980001] -> wl_surface#7.commit()
[00:00:00.020000] -> wl_surface#7.damage(0, 0, 100, 100)
[00:00:00.020001] -> wl_surface#7.commit()
'''.splitlines()
        state = trace.analyze(lines)['surfaces']['7']
        self.assertAlmostEqual(state['buffer_or_damage']['median_ms'], 40)
        self.assertEqual(trace.analyze(['non-protocol log'])['protocol_lines'], 0)


if __name__ == '__main__':
    unittest.main()
